    receive() external payable {}

    function run(address from, address to, uint256 amount) public {
        uint256 balBefore = c.balanceOf(from); if (__ESBMC_reverted()) return;
        uint256 allowBefore = c.allowance(from, msg.sender); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transferFrom(from, to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool shouldSucceed = amount <= balBefore && amount <= allowBefore;

        assert(reverted != shouldSucceed);
    }
}

