        c = new GSPFunding();
    }

    function _run(address from, address to, uint256 amount) internal {
        uint256 balBefore;
        try c.balanceOf(from) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 allowBefore;
        try c.allowance(from, msg.sender) returns (uint256 __r) { allowBefore = __r; } catch { return; }
        bool reverted;
        try c.transferFrom(from, to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool shouldSucceed = amount <= balBefore && amount <= allowBefore;
        assertTrue(reverted != shouldSucceed);
